var i=`0437-raspeballer`;var o=`world-0437`;var n=`NO`;var a=`northern-europe`;var l=4;var s=55;var r={en:`Raspeballer`,ua:`Распебаллер`};var u={en:`A traditional dish from Norway, centered on potato, barley flour, all-purpose flour, bacon. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: картопля, ячмінне борошно, пшеничне борошно універсальне, бекон. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`potato`,800,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`barley-flour`,100,`g`],[`all-purpose-flour`,100,`g`],[`table-salt`,null,`to_taste`]]},{en:`Cook dumplings in batches in gently boiling salted water for about 32 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 32 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:32,i:[[`water`,1500,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`bacon`,120,`g`],[`unsalted-butter`,50,`g`]]}];var d={slug:i,id:o,country:`NO`,region:a,servings:4,minutes:55,title:r,text:u,steps:g};export{n as country,d as default,o as id,s as minutes,a as region,l as servings,i as slug,g as steps,u as text,r as title};